35	export class NzTextareaCountComponent implements AfterContentInit {
36	  private renderer = inject(Renderer2);
37	  private destroyRef = inject(DestroyRef);
38	  private elementRef: ElementRef<HTMLElement> = inject(ElementRef);
39	
40	  @ContentChild(NzInputDirective, { static: true }) nzInputDirective!: NzInputDirective;
41	  @Input({ transform: numberAttribute }) nzMaxCharacterCount: number = 0;
42	  @Input() nzComputeCharacterCount: (v: string) => number = v => v.length;
43	  @Input() nzFormatter: (cur: number, max: number) => string = (c, m) => `${c}${m > 0 ? `/${m}` : ``}`;
44	
45	  ngAfterContentInit(): void {
46	    if (!this.nzInputDirective && isDevMode()) {
47	      throw new Error('[nz-textarea-count]: Could not find matching textarea[nz-input] child.');
48	    }
49	
50	    if (this.nzInputDirective.ngControl) {
51	      const valueChanges = this.nzInputDirective.ngControl.valueChanges || EMPTY;
52	      valueChanges
53	        .pipe(
54	          takeUntilDestroyed(this.destroyRef),
55	          map(() => this.nzInputDirective.ngControl!.value),
56	          startWith(this.nzInputDirective.ngControl.value as string)
57	        )
58	        .subscribe(value => {
59	          this.setDataCount(value);
60	        });
61	    }
62	  }
63	
64	  setDataCount(value: string): void {
65	    const inputValue = isNotNil(value) ? String(value) : '';
66	    const currentCount = this.nzComputeCharacterCount(inputValue);
67	    const dataCount = this.nzFormatter(currentCount, this.nzMaxCharacterCount);
68	    this.renderer.setAttribute(this.elementRef.nativeElement, 'data-count', dataCount);
69	  }
70	}
