48	    '[class.ant-input-underlined]': `nzVariant() === 'underlined'`,
49	    '[class.ant-input-lg]': `finalSize() === 'large'`,
50	    '[class.ant-input-sm]': `finalSize() === 'small'`,
51	    '[attr.disabled]': 'finalDisabled() || null',
52	    '[attr.readonly]': 'readonly() || null',
53	    '[class.ant-input-rtl]': `dir() === 'rtl'`,
54	    '[class.ant-input-stepperless]': `nzStepperless()`,
