56	  },
57	  hostDirectives: [NzSpaceCompactItemDirective],
58	  providers: [{ provide: NZ_SPACE_COMPACT_ITEM_TYPE, useValue: 'input' }]
59	})
60	export class NzInputDirective implements OnInit {
61	  private elementRef = inject<ElementRef<HTMLInputElement | HTMLTextAreaElement>>(ElementRef);
62	  private compactSize = inject(NZ_SPACE_COMPACT_SIZE, { optional: true });
63	  private destroyRef = inject(DestroyRef);
64	  private nzFormStatusService = inject(NzFormStatusService, { optional: true });
65	  private nzFormNoStatusService = inject(NzFormNoStatusService, { optional: true });
66	  private inputWrapper = inject(NZ_INPUT_WRAPPER, { host: true, optional: true });
67	  private focusMonitor = inject(FocusMonitor);
68	  private hostView = inject(ViewContainerRef);
69	  private readonly inputPasswordDir = inject(NzInputPasswordDirective, { host: true, optional: true });
70	  private readonly inputSearchDir = inject(NZ_INPUT_SEARCH, { host: true, optional: true });
71	
72	  readonly ngControl = inject(NgControl, { self: true, optional: true });
73	  readonly value = signal<string>(this.elementRef.nativeElement.value);
74	
75	  readonly nzVariant = input<NzVariant>('outlined');
76	  readonly nzSize = input<NzSizeLDSType>('default');
77	  /**
78	   * @deprecated Will be removed in v22.
79	   */
80	  readonly nzStepperless = input(true, { transform: booleanAttribute });
81	  readonly nzStatus = input<NzStatus>('');
82	  readonly disabled = input(false, { transform: booleanAttribute });
83	  readonly readonly = input(false, { transform: booleanAttribute });
84	
85	  readonly controlDisabled = signal(false);
86	  readonly finalDisabled = this.ngControl ? this.controlDisabled : this.disabled;
87	  readonly dir = inject(Directionality).valueSignal;
88	  // TODO: When the input group is removed, we can remove this.
89	  readonly size = linkedSignal(this.nzSize);
90	
91	  readonly status = this.nzFormStatusService
92	    ? toSignal(this.nzFormStatusService.formStatusChanges.pipe(map(value => value.status)), { initialValue: '' })
93	    : this.nzStatus;
94	  readonly hasFeedback = toSignal(
95	    this.nzFormStatusService?.formStatusChanges.pipe(map(value => value.hasFeedback)) ?? EMPTY,
96	    { initialValue: false }
97	  );
98	  readonly classes = computed(() => getStatusClassNames(PREFIX_CLS, this.status(), this.hasFeedback()));
99	  readonly type = computed(() => {
100	    if (this.inputPasswordDir) {
101	      return this.inputPasswordDir.nzVisible() ? 'text' : 'password';
102	    }
103	    if (this.inputSearchDir) {
104	      return 'search';
105	    }
106	    return this.elementRef.nativeElement.getAttribute('type') || 'text';
107	  });
108	
109	  protected readonly focused = signal<boolean>(false);
110	  protected readonly finalSize = computed(() => {
111	    if (this.compactSize) {
112	      return this.compactSize();
113	    }
114	    return this.size();
115	  });
116	
117	  feedbackRef: ComponentRef<NzFormItemFeedbackIconComponent> | null = null;
118	  // TODO: When the input group is removed, we can remove this.
119	  disabled$ = toObservable(this.finalDisabled);
120	
121	  constructor() {
122	    this.destroyRef.onDestroy(() => {
123	      this.focusMonitor.stopMonitoring(this.elementRef);
124	    });
125	
126	    this.focusMonitor
127	      .monitor(this.elementRef, false)
128	      .pipe(takeUntilDestroyed())
129	      .subscribe(origin => this.focused.set(!!origin));
130	
131	    effect(() => {
132	      this.renderFeedbackIcon();
133	    });
134	  }
135	
136	  ngOnInit(): void {
137	    // statusChanges is only accessible in onInit
138	    this.ngControl?.statusChanges?.pipe(startWith(null), takeUntilDestroyed(this.destroyRef)).subscribe(() => {
139	      this.controlDisabled.set(!!this.ngControl!.disabled);
140	    });
141	
142	    this.ngControl?.valueChanges?.pipe(takeUntilDestroyed(this.destroyRef)).subscribe(value => {
143	      this.value.set(value);
144	    });
145	  }
146	
147	  private renderFeedbackIcon(): void {
148	    if (!this.status() || !this.hasFeedback() || this.inputWrapper || !!this.nzFormNoStatusService) {
149	      // remove feedback
150	      this.hostView.clear();
151	      this.feedbackRef = null;
152	      return;
153	    }
154	
155	    this.feedbackRef = this.feedbackRef || this.hostView.createComponent(NzFormItemFeedbackIconComponent);
156	    this.feedbackRef.location.nativeElement.classList.add('ant-input-suffix');
157	    this.feedbackRef.instance.status = this.status();
158	    this.feedbackRef.instance.updateIcon();
159	  }
160	
161	  focus(options?: InputFocusOptions): void {
162	    triggerFocus(this.elementRef.nativeElement, options);
163	  }
164	
165	  blur(): void {
166	    this.elementRef.nativeElement.blur();
167	  }
168	}
